func (c *DiesisStakingBinding) WatchValidatorSuspended(ctx context.Context, indexed ...[]any) (<-chan DiesisStakingValidatorSuspendedEvent, event.Subscription, error) {
	if c.backend == nil {
		return nil, nil, fmt.Errorf("DiesisStakingBinding has no backend")
	}
	definition, err := c.event("ValidatorSuspended(uint256,uint256,uint256,uint256)")
	if err != nil {
		return nil, nil, err
	}
	count := 0
	for _, arg := range definition.Inputs {
		if arg.Indexed {
			count++
		}
	}
	if len(indexed) > count {
		return nil, nil, fmt.Errorf("too many indexed filters for %s", "ValidatorSuspended(uint256,uint256,uint256,uint256)")
	}
	queries := indexed
	queries = append([][]any{{definition.ID}}, queries...)
	topics, err := abi.MakeTopics(queries...)
	if err != nil {
		return nil, nil, err
	}
	logs := make(chan types.Log)
	upstream, err := c.backend.SubscribeFilterLogs(ctx, ethereum.FilterQuery{Addresses: []common.Address{c.address}, Topics: topics}, logs)
	if err != nil {
		return nil, nil, err
	}
	events := make(chan DiesisStakingValidatorSuspendedEvent)
	subscription := event.NewSubscription(func(quit <-chan struct{}) error {
		defer upstream.Unsubscribe()
		defer close(events)
		for {
			select {
			case <-quit:
				return nil
			case <-ctx.Done():
				return ctx.Err()
			case err, ok := <-upstream.Err():
				if !ok {
					return nil
				}
				return err
			case log, ok := <-logs:
				if !ok {
					return nil
				}
				decoded, err := c.DecodeValidatorSuspendedEvent(log)
				if err != nil {
					return err
				}
				select {
				case events <- decoded:
				case <-quit:
					return nil
				case <-ctx.Done():
					return ctx.Err()
				}
			}
		}
	})
	return events, subscription, nil
}

